{
  "name": "Sonnet 4 - Custom Tools Test",
  "function_name": "remote",
  "description": "Bedrock Claude model for custom tools agent testing",
  "connector": {
    "name": "Amazon Bedrock Claude connector",
    "description": "Connector to Amazon Bedrock service for the Claude model",
    "version": 1,
    "protocol": "aws_sigv4",
    "parameters": {
      "region": "us-east-1",
      "service_name": "bedrock",
      "model": "us.anthropic.claude-sonnet-4-20250514-v1:0"
    },
    "credential": {
      "access_key": "{{aws_access_key}}",
      "secret_key": "{{aws_secret_key}}",
      "session_token": "{{aws_session_token}}"
    },
    "actions": [
      {
        "action_type": "predict",
        "method": "POST",
        "url": "https://bedrock-runtime.${parameters.region}.amazonaws.com/model/${parameters.model}/converse",
        "headers": { "content-type": "application/json" },
        "request_body": "{ \"system\": [{\"text\": \"${parameters.system_prompt}\"}], \"messages\": [${parameters._chat_history:-}{\"role\":\"user\",\"content\":[{\"text\":\"${parameters.prompt}\"}]}${parameters._interactions:-}]${parameters.tool_configs:-} }"
      }
    ]
  }
}

{
  "name": "GeoSearch",
  "description": "Search locations by name within a geographic radius",
  "type": "search_template",
  "search_template_name": "geo_search",
  "index": "locations",
  "params": {
    "search_text": { "type": "string", "description": "Search text for location name", "required": true },
    "radius": { "type": "string", "description": "Search radius (e.g., '10km')", "required": true },
    "lat": { "type": "number", "description": "Latitude of center point", "required": true },
    "lon": { "type": "number", "description": "Longitude of center point", "required": true },
    "size": { "type": "number", "description": "Max results to return", "required": false, "default": "10" }
  }
}

{
  "name": "TestChat_CustomTools",
  "type": "conversational",
  "description": "Chat agent for testing custom SearchTemplateTool resolution",
  "tools": [
    { "type": "SearchTemplateTool", "name": "ProductSearch" },
    { "type": "ListIndexTool" }
  ],
  "llm": {
    "model_id": "{{model_id}}",
    "parameters": { "prompt": "${parameters.question}" }
  },
  "parameters": { "_llm_interface": "bedrock/converse/claude" },
  "memory": { "type": "conversation_index" }
}

{
  "name": "TestPER_CustomTools",
  "type": "PLAN_EXECUTE_AND_REFLECT",
  "description": "PER agent for testing custom SearchTemplateTool resolution",
  "tools": [
    { "type": "SearchTemplateTool", "name": "ProductSearch" },
    { "type": "ListIndexTool" }
  ],
  "llm": {
    "model_id": "{{model_id}}",
    "parameters": { "prompt": "${parameters.question}" }
  },
  "parameters": { "_llm_interface": "bedrock/converse/claude" },
  "memory": { "type": "conversation_index" }
}

